/**
 * dshuf: Shuffle media items within galleries that are within `<div class="dshuf">`.
 *
 * Example: <https://commons.wikimedia.org/wiki/Commons:Picture_of_the_Year/2009/Galleries/Artworks/1>
 *
 * Maintainers: [[User:Dschwen]], [[User:Krinkle]]
 */
function gallery_dshuf($c) {
    $c.find('div.dshuf > ul.gallery').each( function (i, listParent) {
        /** @type {Array<HTMLElement>} */
        var items = $(listParent).children('li.gallerybox').get();
        // sort at random
        items.sort(function () {
            return 0.5 - Math.random();
        });
        // re-append to the parent in the new random order
        items.forEach(function (item) { 
        	listParent.appendChild(item);
        });
    });
}
mw.hook( 'wikipage.content' ).add( gallery_dshuf );

/**
 * dshufset: Shuffle DIV elements across a page from a set of elements with the same set number.
 *
 * Example: <https://commons.wikimedia.org/wiki/Commons:Picture_of_the_Year/2010/Results/R1/Category_winners> 
 * 
 * Each DIV element needs to have a class of "dshuf" and a class of "dshufsetX" where X is a number identifying
 * a particular set of DIV elements that should be shuffled amongst each other. 
 *
 *
 * Maintainers: [[User:Gmaxwell]], [[User:Dschwen]], [[User:Krinkle]]
 */
function dshufset($c) {
 var shufsets = {};
 var rx = /(?:^|\s+)dshufset(\d+)(?:\s+|$)/;
 var $divs = $('div.dshuf[class*="dshufset"]');

 function sortFunction() {
   return 0.5 - Math.random();
 }

 $divs.each(function (i, div) {
   var m = rx.exec(div.className);
   if (!m || !m[1]) {
     return; // Ignore, this one is missing a number
   }
   if (!shufsets[m[1]]) {
     shufsets[m[1]] = []; // First item in a set
   }
   shufsets[m[1]].push(div);
 });

 var original, shuffled, item;
 for (var shufset in shufsets) {
   original = shufsets[shufset].slice();
   shuffled = shufsets[shufset].sort(sortFunction);
   // Insert placeholders
   for (var i = 0; i < original.length; i++) {
     item = original[i];
     original[i] = document.createComment('tmp');
     item.parentNode.replaceChild(original[i], item);
   }
   // Replace placeholders
   for (var j = 0; j < original.length; j++) {
     original[j].parentNode.replaceChild(shuffled[j], original[j]);
   }
 }
}
mw.hook( 'wikipage.content' ).add( dshufset );


