// Note Firefox 66 does not have support for replaceAll so this is wrapped in a try/catch.
let matchPoty = null;
try {
	matchPoty = mw.config.get("wgPageName")
		.replaceAll("_", " ")
		.match(/Picture of the Year\/(\d{4})/);
} catch ( e ) {
    // pass.
}
if (matchPoty && Number(matchPoty[1]) >= 2023) {
    mw.loader.load("/w/index.php?title=MediaWiki:POTY-gallery.js&action=raw&ctype=text/javascript");
}
